@import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@600;700;800&family=Nunito:wght@600;700;800;900&display=swap');
:root{--ink:#243847;--cream:#fff8df;--orange:#f47b35;--blue:#43b9d1;--shadow:0 12px 30px #224e6230}*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:#d7f0ef;font-family:'Nunito',system-ui,sans-serif;color:var(--ink);touch-action:none}.game-shell{position:relative;width:100vw;height:100dvh;min-height:440px;overflow:hidden;background:#a5e0e9}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:3;top:0;left:0;right:0;height:76px;padding:12px 25px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,#fff8e9f2,#fff8e9df);box-shadow:0 3px 14px #345d6120}.brand{border:0;background:none;color:var(--ink);display:flex;align-items:center;gap:10px;font:900 15px 'Nunoo',sans-serif;letter-spacing:1px;cursor:pointer}.brand b{color:#ed7134}.brand-mark{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:#f47b35;color:#fff;font:900 25px 'Baloo 2',sans-serif;box-shadow:inset 0 -4px #d45c24}.level-name{text-align:center;line-height:1}.chapter{display:block;color:#9da5a2;font-size:9px;font-weight:900;letter-spacing:2px;margin-bottom:5px}.level-name strong{font:800 17px 'Baloo 2';letter-spacing:1px}.top-actions{display:flex;gap:8px}.icon-btn,.round-control{border:2px solid #e8dfc9;background:#fff9eb;color:#45535a;border-radius:13px;width:40px;height:40px;font-size:19px;font-weight:900;box-shadow:0 3px 0 #dfd4b8;cursor:pointer}.icon-btn:active,.round-control:active{transform:translateY(2px);box-shadow:0 1px 0 #dfd4b8}.hud-left{position:absolute;z-index:2;top:94px;left:22px;display:flex;flex-direction:column;gap:9px}.mission-card,.score-card{background:#fff9ebed;border:2px solid #fff;box-shadow:var(--shadow);border-radius:14px;display:flex;align-items:center}.mission-card{padding:9px 14px 9px 10px;gap:10px;min-width:212px}.mission-icon{font-size:21px;width:34px;height:34px;background:#fff0c8;border-radius:10px;display:grid;place-items:center}.mission-card small,.score-card small{display:block;font-size:8px;color:#a8a08b;font-weight:900;letter-spacing:1.5px}.mission-card strong{font-size:11px;font-weight:900}.score-card{padding:7px 12px;display:block;width:max-content;min-width:105px}.score-card strong{display:block;font:800 21px 'Baloo 2';letter-spacing:2px;color:#df7538;line-height:1.1}.level-progress{position:absolute;z-index:2;top:100px;right:24px;width:150px;text-align:right}.progress-track{height:9px;border-radius:9px;background:#ffffffa8;border:2px solid #fff;overflow:hidden;box-shadow:0 2px 6px #35596520}.progress-track i{height:100%;width:0;display:block;background:linear-gradient(90deg,#f6a442,#ee7136);border-radius:8px;transition:width .35s}.level-progress span{display:block;margin-top:5px;color:#fff;font-size:9px;font-weight:900;letter-spacing:1px;text-shadow:0 1px 3px #387184}.bird-tray{position:absolute;z-index:2;top:158px;left:22px;padding:7px 11px;background:#ffffffb8;border:1px solid #ffffffd9;border-radius:12px;display:flex;align-items:center;gap:8px;min-height:43px}.tray-label{font-size:8px;font-weight:900;letter-spacing:1px;color:#8b9b99}#birdIcons{display:flex;gap:4px}.bird-dot{font-size:21px;line-height:1;filter:drop-shadow(0 2px 1px #66543b66)}.bird-dot.used{filter:grayscale(1);opacity:.28}.mode-switch{position:absolute;z-index:3;top:91px;left:50%;transform:translateX(-50%);padding:4px;background:#fff9e9e8;border:2px solid #fff;border-radius:14px;display:flex;gap:3px;box-shadow:0 5px 15px #325b6221}.mode-tab{border:0;border-radius:10px;padding:8px 13px;background:transparent;color:#899293;font:900 10px 'Nunito';letter-spacing:.6px;cursor:pointer;white-space:nowrap}.mode-tab span{font-size:15px;vertical-align:-2px;margin-right:4px}.mode-tab.active{background:#f47b35;color:#fff;box-shadow:inset 0 -3px #d9652e}.mode-tab.active#buildTab{background:#45af8c;box-shadow:inset 0 -3px #318f70}.action-hint{position:absolute;z-index:2;left:50%;bottom:88px;transform:translateX(-50%);border-radius:20px;padding:8px 15px;background:#fff9e9df;color:#62757a;font-size:9px;font-weight:900;letter-spacing:1px;box-shadow:0 4px 12px #345c6220;white-space:nowrap}.hint-key{display:inline-grid;place-items:center;background:#f5a342;color:#fff;border-radius:5px;padding:3px 6px;margin-right:5px;font-size:8px}.hint-arrow{color:#f47b35;font-size:15px;margin-left:6px;vertical-align:-1px}.bottom-controls{position:absolute;z-index:3;left:22px;bottom:19px;right:22px;display:flex;align-items:center;gap:12px}.round-control{width:43px;height:43px;border-radius:50%;font-size:24px;color:#f07835}.control-tip{padding:8px 13px;border-radius:11px;background:#fff9e9db;font-size:10px;font-weight:800;color:#718184;box-shadow:0 4px 12px #345c621c}.next-btn,.drive-btn{border:0;border-radius:11px;background:linear-gradient(#ff9850,#ef7136);color:#fff;font:900 11px 'Nunito';letter-spacing:1px;padding:12px 17px;box-shadow:inset 0 -4px #d35e2a,0 5px 11px #99431638;cursor:pointer}.next-btn{margin-left:auto}.next-btn span{font-size:17px;margin-left:9px}.hidden{display:none!important}.build-panel{position:absolute;z-index:3;right:20px;bottom:78px;width:292px;padding:14px;border:2px solid white;border-radius:16px;background:#fff9ebed;box-shadow:var(--shadow)}.panel-title{display:flex;align-items:center;gap:9px;margin-bottom:12px}.panel-title>span{display:grid;place-items:center;width:35px;height:35px;background:#d9f2e7;border-radius:10px;font-size:19px}.panel-title b{display:block;font-size:12px;letter-spacing:1px}.panel-title small{display:block;font-size:9px;color:#9a9b8c;font-weight:800}.parts-row{display:flex;gap:6px}.part{flex:1;min-width:0;border:2px solid #ece5d2;border-radius:10px;background:#fffdf5;padding:6px 3px 5px;color:#77827e;cursor:pointer}.part.active{border-color:#47b68f;background:#e8f8ef;color:#328463}.part-icon{display:block;height:22px;font-size:21px;line-height:20px}.wood-icon{color:#b8793e}.wheel-icon{color:#48545c}.balloon-icon{font-size:17px}.part b{display:block;font-size:8px;letter-spacing:.8px}.panel-hint{font-size:9px;font-weight:800;color:#97a09a;margin:9px 0}.build-actions{display:flex;gap:6px}.soft-btn{border:0;border-radius:8px;background:#eef0e8;color:#77817a;padding:9px 10px;font:900 9px 'Nunito';cursor:pointer}.drive-btn{padding:10px 12px;flex:1;background:linear-gradient(#5bc39e,#3cae88);box-shadow:inset 0 -4px #278b6c,0 5px 10px #3573552c}.notice{position:absolute;z-index:10;top:75px;left:50%;transform:translate(-50%,-20px);padding:10px 18px;border-radius:20px;background:#293f49;color:#fff;font-weight:900;font-size:11px;opacity:0;transition:.22s;pointer-events:none;white-space:nowrap}.notice.show{opacity:1;transform:translate(-50%,0)}.modal,.pause-overlay,.result-overlay{position:absolute;z-index:20;inset:0;display:grid;place-items:center;background:#183c4c62;backdrop-filter:blur(4px);transition:opacity .25s}.modal-card,.pause-card,.result-card{width:min(490px,calc(100vw - 32px));padding:25px 28px 20px;border:3px solid #fff;border-radius:25px;background:#fff9e9;text-align:center;box-shadow:0 20px 70px #1639445c;animation:pop .4s cubic-bezier(.2,1.3,.5,1)}@keyframes pop{from{transform:scale(.8);opacity:0}to{transform:scale(1);opacity:1}}.modal-logo{margin:-48px auto 10px;width:57px;height:57px;border:4px solid #fff;border-radius:18px;background:#f47b35;color:#fff;font:900 34px 'Baloo 2';display:grid;place-items:center;box-shadow:0 5px 0 #c95d29}.eyebrow{font-size:9px;font-weight:900;letter-spacing:2px;color:#d8954c;margin:12px 0 4px}.modal-card h1{font:900 36px/.87 'Baloo 2';letter-spacing:2px;margin:6px 0;color:#31515c;text-shadow:0 2px #dce5d2}.modal-card h1 em{font-style:normal;color:#ef783b}.modal-copy{font-size:12px;line-height:1.5;font-weight:700;color:#778885;margin:12px 0 18px}.mode-cards{display:flex;gap:10px}.choice-card{position:relative;flex:1;text-align:left;border:2px solid #f0dfc0;border-radius:15px;padding:11px 11px 10px;background:#fffdf6;color:#38515a;cursor:pointer;transition:transform .15s,border .15s;box-shadow:0 4px 0 #ead9bb}.choice-card:hover{transform:translateY(-3px);border-color:#f5a256}.choice-card.pig-card{background:#f2fbf1;border-color:#d6e8cd}.choice-art{float:right;font-size:29px;filter:drop-shadow(0 3px 1px #8678534d)}.choice-card b,.choice-card small{display:block}.choice-card b{font-size:11px;letter-spacing:.4px;margin-top:8px}.choice-card small{font-size:9px;color:#9a9e8e;font-weight:800;margin-top:3px}.choice-arrow{display:block;margin-top:12px;font-size:9px;font-weight:900;letter-spacing:1px;color:#ed7838}.pig-card .choice-arrow{color:#3fa87e}.modal-foot{margin-top:17px;font-size:9px;color:#a6a18f;font-weight:800;letter-spacing:.5px}.pause-overlay,.result-overlay{z-index:12}.pause-card,.result-card{width:min(360px,calc(100vw - 32px));padding:25px}.pause-card>span{font-size:34px;color:#45b68e}.pause-card h2,.result-card h2{font:900 23px 'Baloo 2';letter-spacing:1px;color:#31515c;margin:6px 0}.pause-card p,.result-card p{font-size:11px;color:#87928b;font-weight:700}.pause-card .drive-btn,.result-card .drive-btn{margin-top:12px;width:100%;font-size:10px}.result-emoji{font-size:45px}.result-score{margin:15px auto 5px;padding:8px;width:150px;border-radius:12px;background:#fff0d4}.result-score small,.result-score b{display:block}.result-score small{font-size:8px;color:#aa9a73;letter-spacing:1px;font-weight:900}.result-score b{font:800 24px 'Baloo 2';color:#ed7838;letter-spacing:2px}.text-btn{display:block;border:0;background:none;color:#96998e;font:900 9px 'Nunito';letter-spacing:.7px;margin:15px auto 0;cursor:pointer}.result-card .eyebrow{margin-top:4px}.pause-overlay.hidden,.result-overlay.hidden{display:none}
@media(max-width:700px){.topbar{height:62px;padding:8px 12px}.brand{gap:7px;font-size:11px;letter-spacing:.5px}.brand-mark{height:35px;width:35px;border-radius:12px;font-size:22px}.level-name strong{font-size:14px}.icon-btn{width:35px;height:35px}.top-actions{gap:5px}.hud-left{top:73px;left:10px;gap:6px}.mission-card{min-width:0;padding:6px 9px 6px 6px;gap:6px}.mission-icon{width:28px;height:28px;font-size:17px}.mission-card small,.score-card small{font-size:7px}.mission-card strong{font-size:9px}.score-card{padding:5px 8px;min-width:78px}.score-card strong{font-size:17px}.mode-switch{top:69px}.mode-tab{font-size:8px;padding:7px 8px}.mode-tab span{font-size:13px}.level-progress{top:115px;right:12px;width:105px}.level-progress span{font-size:7px}.bird-tray{top:132px;left:10px;padding:5px 8px;min-height:32px}.bird-dot{font-size:17px}.tray-label{font-size:7px}.action-hint{bottom:74px;font-size:8px;padding:7px 11px}.bottom-controls{left:10px;right:10px;bottom:10px;gap:7px}.round-control{width:37px;height:37px}.control-tip{font-size:8px;padding:7px 8px;max-width:45%;line-height:1.2}.next-btn{font-size:9px;padding:10px 11px}.build-panel{right:10px;bottom:62px;width:min(260px,calc(100vw - 20px));padding:10px}.panel-title{margin-bottom:8px}.panel-title>span{width:30px;height:30px}.panel-hint{margin:7px 0}.modal-card{padding:22px 18px 17px}.modal-card h1{font-size:31px}.modal-copy{font-size:11px}.mode-cards{gap:7px}.choice-card{padding:8px}.choice-card b{font-size:9px}.choice-card small{font-size:8px}.choice-art{font-size:25px}.choice-arrow{font-size:8px;margin-top:9px}.modal-foot{margin-top:13px}.notice{top:62px;font-size:10px}}
@media(max-height:560px){.modal-card{transform:scale(.84);}.modal-logo{margin-top:-35px}.mode-switch{top:67px}.hud-left{top:70px}.bird-tray{top:130px}.action-hint{bottom:60px}.bottom-controls{bottom:7px}.build-panel{bottom:55px;transform:scale(.9);transform-origin:bottom right}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { score:$('score'), progress:$('progressFill'), progressText:$('progressText'), tray:$('birdIcons'), title:$('levelTitle'), mission:$('missionText'), hint:$('controlTip'), action:$('actionHint'), build:$('buildPanel'), notice:$('notice'), modal:$('modal'), pause:$('pauseOverlay'), result:$('resultOverlay') };
  const W=1000,H=600, GRAVITY=470;
  let viewW=innerWidth,viewH=innerHeight,dpr=1,scaleX=1,scaleY=1;
  const colors={sky:'#9cdeeb',grass:'#78c873',wood:'#ce9558',woodTop:'#edbd79',woodSide:'#a96d40',stone:'#94a5a4',stoneTop:'#c3d0c4',stoneSide:'#728481'};
  let mode='attack',level=0,score=0, birds=[], pigs=[], blocks=[], effects=[], clouds=[], sling={x:170,y:442}, currentBird=null, dragging=false, dragPos=null, launched=false, gameOver=false, paused=false, buildPart='wood', buildObjects=[], buildHistory=[], driving=false, driveTime=0, vehicle={x:300,y:0,vx:0,vy:0,angle:0}, sound=true, lastTime=0, noticeTimer=0, particles=[];
  const levels=[
    {name:'PIGGY PEAK',mission:'Knock down the pig fort!',pigs:3,birds:['red','yellow','red'],fort:'tower'},
    {name:'TIMBER TROUBLE',mission:'Send the piggies packing!',pigs:4,birds:['yellow','red','blue','red'],fort:'bridge'},
    {name:'CLOUD NINE',mission:'Clear the skies of swine!',pigs:4,birds:['red','yellow','blue','yellow'],fort:'cloud'}
  ];
  function resize(){viewW=innerWidth;viewH=innerHeight;dpr=Math.min(devicePixelRatio||1,2);canvas.width=viewW*dpr;canvas.height=viewH*dpr;canvas.style.width=viewW+'px';canvas.style.height=viewH+'px';scaleX=viewW/W;scaleY=viewH/H;ctx.setTransform(dpr*scaleX,0,0,dpr*scaleY,0,0)}
  addEventListener('resize',resize);resize();
  function rand(a,b){return a+Math.random()*(b-a)}
  function levelSetup(){const l=levels[level%levels.length];ui.title.textContent=l.name;ui.mission.textContent=l.mission;score=0;updateScore();gameOver=false;paused=false;launched=false;dragging=false;driving=false;effects=[];particles=[];buildObjects=[];buildHistory=[];birds=l.birds.map((type,i)=>({type,x:170-i*38,y:442,r:type==='blue'?16:20,active:i===0,used:false,vx:0,vy:0,rotation:0,alive:true})); pigs=[];blocks=[];
    if(l.fort==='tower'){blocks.push(box(730,432,26,82,'wood'),box(812,432,26,82,'wood'),box(771,378,108,20,'wood'),box(730,339,24,57,'wood'),box(812,339,24,57,'wood'),box(771,302,100,18,'stone'),box(771,270,24,42,'wood'));pigs.push(pig(772,419),pig(755,325),pig(771,254));}
    if(l.fort==='bridge'){blocks.push(box(690,442,22,72,'wood'),box(780,442,22,72,'wood'),box(870,442,22,72,'wood'),box(735,392,92,18,'wood'),box(825,392,92,18,'wood'),box(780,342,22,83,'stone'),box(825,342,22,83,'stone'),box(802,292,108,18,'wood'),box(780,267,20,34,'wood'),box(825,267,20,34,'wood'));pigs.push(pig(735,422),pig(825,422),pig(802,315),pig(802,249));}
    if(l.fort==='cloud'){blocks.push(box(700,438,25,82,'stone'),box(790,438,25,82,'stone'),box(745,388,115,18,'wood'),box(720,347,22,46,'wood'),box(770,347,22,46,'wood'),box(745,313,78,17,'stone'),box(835,438,20,68,'wood'));pigs.push(pig(745,365),pig(744,296),pig(835,420),pig(700,420));}
    updateTray();updateProgress();ui.result.classList.add('hidden');$('nextBtn').classList.add('hidden');ui.hint.textContent=mode==='attack'?'Drag the bird back, then let it fly!':'Tap the parts to build your getaway!';
  }
  function box(x,y,w,h,material='wood'){return {x,y,w,h,material,vx:0,vy:0,angle:0,hp:material==='stone'?2:1,alive:true,placed:false}}
  function pig(x,y){return {x,y,r:19,vx:0,vy:0,angle:0,alive:true,grounded:true,blink:0}}
  function updateScore(){ui.score.textContent=String(score).padStart(6,'0')}
  function updateTray(){ui.tray.innerHTML='';birds.forEach(b=>{const s=document.createElement('span');s.className='bird-dot'+(b.used?' used':'');s.textContent=b.type==='yellow'?'🐤':b.type==='blue'?'🐦':'🐦';ui.tray.appendChild(s)})}
  function updateProgress(){const down=levels[level%levels.length].pigs-pigs.filter(p=>p.alive).length;ui.progress.style.width=(down/levels[level%levels.length].pigs*100)+'%';ui.progressText.textContent=`${down} / ${levels[level%levels.length].pigs} PIGS`}
  function notify(text){ui.notice.textContent=text;ui.notice.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>ui.notice.classList.remove('show'),1900)}
  function beginGame(nextMode){mode=nextMode;ui.modal.classList.add('hidden');$('attackTab').classList.toggle('active',mode==='attack');$('buildTab').classList.toggle('active',mode==='build');ui.build.classList.toggle('hidden',mode!=='build');ui.action.classList.toggle('hidden',mode==='build');ui.hint.textContent=mode==='attack'?'Drag the bird back, then let it fly!':'Tap the parts to build your getaway!';levelSetup();if(mode==='build')setupVehicle()}
  function setupVehicle(){vehicle={x:290,y:425,vx:0,vy:0,angle:0};buildObjects=[];buildHistory=[];driving=false;driveTime=0;buildPart='wood';document.querySelectorAll('.part').forEach(p=>p.classList.toggle('active',p.dataset.part==='wood'))}

  function drawBackground(t){const sky=ctx.createLinearGradient(0,0,0,600);sky.addColorStop(0,'#83d3e6');sky.addColorStop(.58,'#b5e7df');sky.addColorStop(1,'#e1edc9');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    // sun, distant hills, soft cloud puffs
    ctx.fillStyle='#ffe9a8';ctx.beginPath();ctx.arc(846,145,44,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff4c2';ctx.beginPath();ctx.arc(846,145,34,0,Math.PI*2);ctx.fill();
    ctx.fillStyle='#9dcfba';ctx.beginPath();ctx.moveTo(0,357);ctx.quadraticCurveTo(170,245,330,358);ctx.quadraticCurveTo(490,258,675,353);ctx.quadraticCurveTo(825,235,1000,340);ctx.lineTo(1000,500);ctx.lineTo(0,500);ctx.fill();ctx.fillStyle='#82c69f';ctx.beginPath();ctx.moveTo(0,410);ctx.quadraticCurveTo(230,315,430,409);ctx.quadraticCurveTo(670,307,1000,396);ctx.lineTo(1000,520);ctx.lineTo(0,520);ctx.fill();
    clouds.forEach(c=>{c.x-=c.speed*t;if(c.x<-120)c.x=1100;drawCloud(c.x,c.y,c.s)});if(!clouds.length)clouds=[{x:100,y:180,s:.8,speed:5},{x:430,y:230,s:.55,speed:3},{x:990,y:210,s:.9,speed:4}];
    // island ground
    ctx.fillStyle='#83c96d';ctx.beginPath();ctx.moveTo(0,463);ctx.quadraticCurveTo(220,451,400,462);ctx.quadraticCurveTo(740,447,1000,460);ctx.lineTo(1000,600);ctx.lineTo(0,600);ctx.fill();ctx.fillStyle='#5caf62';ctx.beginPath();ctx.moveTo(0,515);ctx.quadraticCurveTo(350,480,600,520);ctx.quadraticCurveTo(810,490,1000,519);ctx.lineTo(1000,600);ctx.lineTo(0,600);ctx.fill();
    for(let i=0;i<30;i++){const x=((i*79+14)%1000),y=474+((i*41)%88);ctx.fillStyle=i%2?'#9cda76':'#68b961';ctx.beginPath();ctx.ellipse(x,y,randStatic(i,2,6),2,0,0,Math.PI*2);ctx.fill()}
    // tiny island rocks
    ctx.fillStyle='#d5cc9d';ctx.beginPath();ctx.ellipse(510,570,85,13,0,0,Math.PI*2);ctx.fill();
    drawSling();
  }
  function randStatic(n,a,b){return a+((n*17)%100)/100*(b-a)}
  function drawCloud(x,y,s){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#ffffff98';ctx.beginPath();ctx.ellipse(0,0,35,13,0,0,Math.PI*2);ctx.ellipse(-17,-6,16,15,0,0,Math.PI*2);ctx.ellipse(1,-12,21,21,0,0,Math.PI*2);ctx.ellipse(20,-5,17,14,0,0,Math.PI*2);ctx.fill();ctx.restore()}
  function drawSling(){ctx.save();ctx.lineCap='round';ctx.lineWidth=12;ctx.strokeStyle='#754a33';ctx.beginPath();ctx.moveTo(165,461);ctx.lineTo(166,408);ctx.quadraticCurveTo(168,393,179,401);ctx.stroke();ctx.beginPath();ctx.moveTo(167,414);ctx.lineTo(147,390);ctx.stroke();ctx.lineWidth=5;ctx.strokeStyle='#c77743';ctx.beginPath();ctx.moveTo(166,410);ctx.lineTo(157,386);ctx.stroke();if(currentBird&&dragging){ctx.strokeStyle='#684333';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(179,402);ctx.lineTo(dragPos.x,dragPos.y);ctx.moveTo(157,386);ctx.lineTo(dragPos.x,dragPos.y);ctx.stroke()}ctx.restore()}

  function drawBox(o){if(!o.alive)return;ctx.save();ctx.translate(o.x,o.y);ctx.rotate(o.angle||0);const {w,h}=o;const d=9;let front=o.material==='stone'?'#9caaa4':'#c89054',top=o.material==='stone'?'#ced8c9':'#edbd79',side=o.material==='stone'?'#738580':'#a66b40';if(o.material==='wheel'){ctx.fillStyle='#35464a';ctx.beginPath();ctx.arc(0,0,w/2,0,Math.PI*2);ctx.fill();ctx.fillStyle='#82908a';ctx.beginPath();ctx.arc(0,0,w*.23,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#c5c6a9';ctx.lineWidth=2;for(let a=0;a<Math.PI*2;a+=Math.PI/4){ctx.beginPath();ctx.moveTo(Math.cos(a)*w*.22,Math.sin(a)*w*.22);ctx.lineTo(Math.cos(a)*w*.43,Math.sin(a)*w*.43);ctx.stroke()}ctx.restore();return}
