import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/opencode/01-menu.jpg', type: 'jpeg', quality: 70 });
console.log('menu', await page.locator('#modal').isVisible());
await page.click('#playAttack');
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/02-attack.jpg', type: 'jpeg', quality: 70 });
// Drag the bird: locate canvas logical sling at (170,442) of 1000x600; viewport scale
const box = await page.locator('#game').boundingBox();
const toScreen = (x, y) => ({ x: box.x + x / 1000 * box.width, y: box.y + y / 600 * box.height });
const down = toScreen(170, 442);
const up = toScreen(95, 470);
await page.mouse.move(down.x, down.y);
await page.mouse.down();
await page.mouse.move(up.x, up.y, { steps: 10 });
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/03-drag.jpg', type: 'jpeg', quality: 70 });
await page.mouse.up();
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/04-fly.jpg', type: 'jpeg', quality: 70 });
await page.waitForTimeout(2500);
console.log('score', await page.locator('#score').textContent(), 'progress', await page.locator('#progressText').textContent());
await page.screenshot({ path: '/tmp/opencode/05-after.jpg', type: 'jpeg', quality: 70 });
console.log('errors', errors);
await browser.close();

