 * ------------------------------------------------------------------ */

const $ = id => document.getElementById(id);
const ui = {
  score: $('score'), scoreLabel: $('scoreLabel'), progress: $('progressFill'), progressText: $('progressText'),
  tray: $('birdIcons'), title: $('levelTitle'), chapter: $('chapterLabel'), mission: $('missionText'),
