import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message); });
page.on('console', m => { if (m.type() === 'error') { errors.push('console: ' + m.text()); console.log('CONSOLE', m.text()); } });
await page.goto('http://localhost:3002/?v=4', { waitUntil: 'load' });
await page.waitForTimeout(2000);
await page.click('#playAttack');
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/4-attack.jpg', type: 'jpeg', quality: 72 });
await page.mouse.move(207, 560);
await page.mouse.down();
await page.mouse.move(145, 648, { steps: 12 });
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/4-drag.jpg', type: 'jpeg', quality: 72 });
await page.mouse.up();
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/4-fly.jpg', type: 'jpeg', quality: 72 });
await page.waitForTimeout(2200);
console.log('score', await page.locator('#score').textContent());
console.log('progress', await page.locator('#progressText').textContent());
await page.screenshot({ path: '/tmp/opencode/4-after.jpg', type: 'jpeg', quality: 72 });
console.log('errors', errors);
await browser.close();

