await page.screenshot({ path: '/tmp/opencode/5-fly.jpg', type: 'jpeg', quality: 75 });
await page.waitForTimeout(3000);
console.log('after', JSON.stringify(await page.evaluate(() => window.__skyway.state)).slice(0, 1200));
console.log('score', await page.locator('#score').textContent(), await page.locator('#progressText').textContent());
await page.screenshot({ path: '/tmp/opencode/5-after.jpg', type: 'jpeg', quality: 75 });
await browser.close();

