import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?v=7', { waitUntil: 'load' });
await page.waitForTimeout(1600);
await page.click('#playAttack');
await page.waitForTimeout(1400);
await page.screenshot({ path: '/tmp/opencode/7-attack.jpg', type: 'jpeg', quality: 80 });
// Try grabbing at the projected bird location
await page.mouse.move(214, 501);
await page.mouse.down();
await page.mouse.move(136, 560, { steps: 12 });
await page.waitForTimeout(350);
console.log('drag state', JSON.stringify(await page.evaluate(() => window.__skyway.state)).slice(-330));
await page.screenshot({ path: '/tmp/opencode/7-drag.jpg', type: 'jpeg', quality: 80 });
await page.mouse.up();
await page.waitForTimeout(900);
console.log('fly', JSON.stringify(await page.evaluate(() => window.__skyway.state)).slice(-330));
await page.screenshot({ path: '/tmp/opencode/7-fly.jpg', type: 'jpeg', quality: 80 });
await browser.close();

import { createRequire } from 'node:module';
