function makePalm(x, y, z, s = 1) {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(unitCylinder, M.woodDark);
  trunk.position.y = 0.42 * s;
  trunk.scale.set(0.05 * s, 0.85 * s, 0.05 * s);
  trunk.rotation.z = 0.08;
  g.add(trunk);
  for (let i = 0; i < 6; i++) {
    const a = i / 6 * Math.PI * 2;
    const leaf = new THREE.Mesh(unitSphere, i % 2 ? M.leaf : M.leafLight);
    leaf.position.set(Math.cos(a) * 0.34 * s, 0.9 * s, Math.sin(a) * 0.34 * s);
    leaf.scale.set(0.44 * s, 0.055 * s, 0.16 * s);
    leaf.rotation.y = -a;
    leaf.rotation.z = 0.22;
    g.add(leaf);
  }
  for (let i = 0; i < 3; i++) {
    const nut = new THREE.Mesh(unitSphere, M.pigDark);
    nut.position.set(rnd(-0.08, 0.08) * s, 0.82 * s, rnd(-0.08, 0.08) * s);
    nut.scale.setScalar(0.06 * s);
    g.add(nut);
  }
  g.position.set(x, y, z);
  env.add(g);
  return g;
}
makePalm(-9.6, 1.85, -18.8, 1.15);
makePalm(6.2, 2.1, -22, 1.35);
makePalm(-12.5, 1.5, -19, 0.9);

/* A few tiny distant islands */
for (const [x, z, s] of [[-8, -16, 1.1], [10, -15, 0.8]]) {
  const isl = new THREE.Mesh(new THREE.CylinderGeometry(1.2 * s, 1.55 * s, 0.5, 20), M.grass);
  isl.position.set(x, -1.1, z);
  env.add(isl);
  makePalm(x, -0.86, z, s * 0.9);
}

