async function fps(label) { const n = await page.evaluate(() => new Promise(res => { let n = 0; const t0 = performance.now(); function f(t) { n++; if (t - t0 < 2000) requestAnimationFrame(f); else res({ n, ms: t - t0 }); } requestAnimationFrame(f); })); console.log(label, (n.n / (n.ms / 1000)).toFixed(1), 'fps', n.n, 'frames'); }
