const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') console.log('CONSOLE', m.type(), m.text()); });
await page.goto('http://localhost:3002/?v=20', { waitUntil: 'load' });
await page.waitForTimeout(1500);

// ---- ATTACK: full level 1 clear via a few shots ----
await page.click('#playAttack');
await page.waitForTimeout(1000);
console.log('attack start', await page.locator('#progressText').textContent());

async function shot(dx, dy) {
  const st = await page.evaluate(() => window.__skyway.state);
  if (st.gameOver || !st.currentBird) return;
  const b = await page.locator('#game').boundingBox();
  // project sling center approx from current bird -> use known mapping via evaluate helper
  const pt = await page.evaluate(([sx, sy]) => {
    const c = document.querySelector('canvas');
    return { w: c.clientWidth, h: c.clientHeight };
  }, [0, 0]);
  const bx = b.x + 214, by = b.y + 501;
  await page.mouse.move(bx, by);
  await page.mouse.down();
  await page.mouse.move(bx + dx, by + dy, { steps: 14 });
  await page.waitForTimeout(350);
  await page.mouse.up();
  await page.waitForTimeout(3200);
}

await shot(-72, 22);
await page.screenshot({ path: '/tmp/opencode/20-attack1.jpg', type: 'jpeg', quality: 80 });
