let s = await page.evaluate(() => window.__skyway.state);
console.log('state', JSON.stringify({ launched: s.launched, pigs: s.pigs.map(p => p.alive), birds: s.birds.map(b => b.used), gameOver: s.gameOver, result: !document_.hidden }));

await shot(-72, 0);
console.log('after shot2', await page.locator('#progressText').textContent(), await page.locator('#score').textContent(), 'result', await page.locator('#resultOverlay').isVisible());
await shot(-60, -10);
console.log('after shot3', await page.locator('#progressText').textContent(), 'result', await page.locator('#resultOverlay').isVisible());

// pause test
await page.keyboard.press('Escape');
console.log('pause visible', await page.locator('#pauseOverlay').isVisible());
await page.keyboard.press('Escape');

await page.screenshot({ path: '/tmp/opencode/20-attack-final.jpg', type: 'jpeg', quality: 80 });
await browser.close();

