const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/?v=21', { waitUntil: 'load' });
await page.waitForTimeout(1500);

function drag(from, to, steps = 14) {
  return page.evaluate(({ from, to }) => ({ from, to }), { from, to }).then(async () => {
    await page.mouse.move(from.x, from.y);
    await page.mouse.down();
    await page.mouse.move(to.x, to.y, { steps });
    await page.waitForTimeout(300);
    return page.evaluate(() => window.__skyway.state.drag);
  });
}

await page.click('#playAttack');
await page.waitForTimeout(1100);
console.log('start', await page.locator('#progressText').textContent());

// shot 1: target top pig at (771, 266) → pull back-left and down
let bird = await page.evaluate(() => window.__skyway.screenOf(170, 390));
let target = await page.evaluate(() => window.__skyway.screenOf(771, 266, 0.5));
console.log('bird screen', bird, 'target screen', target);
let dx = Math.max(-95, Math.min(60, (bird.x - target.x) * 0.22));
let dy = Math.min(80, Math.max(-40, (target.y - bird.y) * 0.22));
let pull = { x: bird.x + dx, y: bird.y + dy };
let d = await drag(bird, pull);
console.log('dragPos', d);
await page.screenshot({ path: '/tmp/opencode/21-drag.jpg', type: 'jpeg', quality: 80 });
await page.mouse.up();
await page.waitForTimeout(3400);
console.log('shot1', await page.locator('#progressText').textContent(), await page.locator('#score').textContent());
await page.screenshot({ path: '/tmp/opencode/21-shot1.jpg', type: 'jpeg', quality: 80 });

for (let i = 2; i <= 3; i++) {
  const st = await page.evaluate(() => window.__skyway.state);
  if (st.gameOver) break;
  const cur = st.currentBird;
  if (!cur) { console.log('no current bird'); break; }
  bird = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
  const aim = await page.evaluate(() => window.__skyway.screenOf(771, 330, 0.5));
  dx = Math.max(-95, Math.min(60, (bird.x - aim.x) * 0.24));
  dy = Math.min(80, Math.max(-30, (aim.y - bird.y) * 0.2));
  await drag(bird, { x: bird.x + dx, y: bird.y + dy });
  await page.mouse.up();
  await page.waitForTimeout(3600);
  console.log(`shot${i}`, await page.locator('#progressText').textContent(), await page.locator('#score').textContent(), 'result', await page.locator('#resultOverlay').isVisible());
  await page.screenshot({ path: `/tmp/opencode/21-shot${i}.jpg`, type: 'jpeg', quality: 80 });
}

console.log('result visible', await page.locator('#resultOverlay').isVisible());
if (await page.locator('#resultOverlay').isVisible()) {
  console.log('result title', await page.locator('#resultTitle').textContent());
  console.log('result button', await page.locator('#resultButton').textContent());
  await page.screenshot({ path: '/tmp/opencode/21-result.jpg', type: 'jpeg', quality: 82 });
  await page.click('#resultButton');
  await page.waitForTimeout(1200);
  console.log('after next', await page.locator('#levelTitle').textContent(), await page.locator('#progressText').textContent());
  await page.screenshot({ path: '/tmp/opencode/21-next.jpg', type: 'jpeg', quality: 82 });
}
await browser.close();

import { createRequire } from 'node:module';
