const G = 470;
function solvePull(from, target) {
  for (let T = 0.45; T <= 2.2; T += 0.02) {
    const vx = (target.x - from.x) / T;
    const vy = (target.y - from.y - 0.5 * G * T * T) / T;
    let f = 1.3;
    let dxp, dyp;
    for (let k = 0; k < 8; k++) {
      vx; 
      dxp = -vx / (5.2 * f);
      dyp = -vy / (5.2 * f);
      const mag = Math.hypot(dxp, dyp);
      f = Math.min(1.75, mag / 72);
      if (mag <= 95) {
        return { dxp, dyp, T, vx, vy, mag };
      }
    }
    if (T > 1.6) break;
  }
  return null;
}

async function pullShot(target, label) {
  const st = await page.evaluate(() => window.__skyway.state);
  if (st.gameOver || !st.currentBird) return console.log(label, 'skip');
  const cur = st.currentBird;
  const pull = solvePull(cur, target);
  if (!pull) return console.log(label, 'no solution');
  console.log(label, 'pull', JSON.stringify(pull));
  const from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
  const to = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x + pull.dxp, cur.y + pull.dyp]);
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  await page.mouse.move(to.x, to.y, { steps: 16 });
  await page.waitForTimeout(250);
  await page.mouse.up();
  await page.waitForTimeout(4200);
  console.log(label, 'progress', await page.locator('#progressText').textContent(), 'score', await page.locator('#score').textContent());
}

await page.click('#playAttack');
await page.waitForTimeout(1100);
await pullShot({ x: 762, y: 300 }, 'shot1'); // top of tower
await page.screenshot({ path: '/tmp/opencode/22-shot1.jpg', type: 'jpeg', quality: 80 });
let st = await page.evaluate(() => window.__skyway.state);
console.log('pigs', st.pigs.map(p => p.alive), 'gameOver', st.gameOver);
if (!st.gameOver) {
  await pullShot({ x: 771, y: 400 }, 'shot2');
  await page.screenshot({ path: '/tmp/opencode/22-shot2.jpg', type: 'jpeg', quality: 80 });
}
st = await page.evaluate(() => window.__skyway.state);
console.log('pigs2', st.pigs.map(p => p.alive), 'gameOver', st.gameOver);
if (!st.gameOver) {
  await pullShot({ x: 800, y: 440 }, 'shot3');
  await page.screenshot({ path: '/tmp/opencode/22-shot3.jpg', type: 'jpeg', quality: 80 });
}
console.log('result', await page.locator('#resultOverlay').isVisible());
if (await page.locator('#resultOverlay').isVisible()) {
  console.log('title', await page.locator('#resultTitle').textContent());
  await page.screenshot({ path: '/tmp/opencode/22-result.jpg', type: 'jpeg', quality: 82 });
}
await browser.close();

