import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/?v=23', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.click('#playBuild');
await page.waitForTimeout(1100);

// Click parts in the build zone: need world->screen. Add temporary helper via evaluate of state? use known clicks from before.
await page.click('[data-part="wheel"]');
await page.mouse.click(286, 518);
await page.mouse.click(356, 518);
await page.click('[data-part="balloon"]');
await page.mouse.click(320, 452);
await page.mouse.click(300, 430);
await page.click('[data-part="wood"]');
await page.mouse.click(320, 492);
console.log('parts', JSON.stringify(await page.evaluate(() => window.__skyway.state.build)));
await page.screenshot({ path: '/tmp/opencode/23-built.jpg', type: 'jpeg', quality: 82 });

await page.click('#driveBtn');
for (let i = 0; i < 12; i++) {
  await page.waitForTimeout(1000);
  const s = await page.evaluate(() => window.__skyway.state);
  const vis = await page.locator('#resultOverlay').isVisible();
  console.log(i + 1, 'x', s.vehicle.x.toFixed(2), 'y', s.vehicle.y.toFixed(2), 'stars', s.stars, 'result', vis);
  if (i === 3) await page.screenshot({ path: '/tmp/opencode/23-drive.jpg', type: 'jpeg', quality: 82 });
  if (vis) break;
}
console.log('title', await page.locator('#resultTitle').textContent());
console.log('copy', await page.locator('#resultCopy').textContent());
console.log('score', await page.locator('#score').textContent());
await page.screenshot({ path: '/tmp/opencode/23-result.jpg', type: 'jpeg', quality: 82 });
await page.click('#resultButton');
await page.waitForTimeout(900);
console.log('after rebuild, parts', (await page.evaluate(() => window.__skyway.state.build)).length, 'result', await page.locator('#resultOverlay').isVisible());
await page.screenshot({ path: '/tmp/opencode/23-retry.jpg', type: 'jpeg', quality: 82 });
await browser.close();

