.bird-dot{position:relative;width:22px;height:22px;border-radius:50%;background:radial-gradient(circle at 34% 28%,#ff9a88,#e14a3c 62%,#c2372b);box-shadow:inset 0 -3px #a92c22,0 2px 3px #66543b55;border:2px solid #fff8ec}
.bird-dot::before{content:"";position:absolute;left:4px;top:8px;width:7px;height:4px;border-radius:50%;background:#fff8ec}
.bird-dot::after{content:"";position:absolute;right:-4px;top:8px;border-left:6px solid #f5ab39;border-top:3px solid transparent;border-bottom:3px solid transparent}
.bird-dot.yellow{background:radial-gradient(circle at 34% 28%,#fff0a0,#f4cf43 62%,#d9ad24);box-shadow:inset 0 -3px #c1991d,0 2px 3px #66543b55}
.bird-dot.blue{width:20px;height:20px;background:radial-gradient(circle at 34% 28%,#9fe4f7,#42b9e8 62%,#2b93bd);box-shadow:inset 0 -3px #2281a8,0 2px 3px #66543b55}
.bird-dot.used{filter:grayscale(1);opacity:.3}

function updateTray() {
  ui.tray.innerHTML = '';
  birds.forEach(b => {
    const s = document.createElement('span');
    s.className = 'bird-dot ' + b.type + (b.used ? ' used' : '');
    s.title = b.type + ' bird' + (b.used ? ' (used)' : '');
    ui.tray.appendChild(s);
  });
}

