let from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
await page.mouse.move(from.x, from.y);
await page.mouse.down();
await page.mouse.move(from.x - 78, from.y + 48, { steps: 14 });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/25-drag.jpg', type: 'jpeg', quality: 85 });
