import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/?v=26', { waitUntil: 'load' });
await page.waitForTimeout(1500);

const G = 470;
function solvePull(from, target) {
  for (let T = 0.4; T <= 2.3; T += 0.02) {
    const vx = (target.x - from.x) / T;
    const vy = (target.y - from.y - 0.5 * G * T * T) / T;
    let f = 1.3, dxp, dyp;
    for (let k = 0; k < 10; k++) {
      dxp = -vx / (5.2 * f);
      dyp = -vy / (5.2 * f);
      const mag = Math.hypot(dxp, dyp);
      f = Math.min(1.75, mag / 72);
      if (mag <= 95) return { dxp, dyp, mag };
    }
  }
  return null;
}
async function shootAt(target, label) {
  const st = await page.evaluate(() => window.__skyway.state);
  if (st.gameOver || !st.currentBird) return false;
  const cur = st.currentBird;
  const pull = solvePull(cur, target);
  if (!pull) { console.log(label, 'NO SOLVE'); return false; }
  const from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
  const to = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x + pull.dxp, cur.y + pull.dyp]);
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  await page.mouse.move(to.x, to.y, { steps: 16 });
  await page.waitForTimeout(200);
  await page.mouse.up();
  await page.waitForTimeout(4000);
  console.log(label, await page.locator('#progressText').textContent(), 'score', await page.locator('#score').textContent());
  return true;
}

await page.click('#playAttack');
await page.waitForTimeout(900);

async function clearLevel(targets, tag) {
  for (let i = 0; i < targets.length; i++) {
    const st = await page.evaluate(() => window.__skyway.state);
    if (st.gameOver) break;
    await shootAt(targets[i], `${tag} shot${i + 1}`);
    if (i === 0) await page.screenshot({ path: `/tmp/opencode/26-${tag}.jpg`, type: 'jpeg', quality: 85 });
    if (await page.locator('#resultOverlay').isVisible()) break;
  }
  const vis = await page.locator('#resultOverlay').isVisible();
  console.log(tag, 'won?', vis, vis ? await page.locator('#resultTitle').textContent() : '');
  return vis;
}

let won = await clearLevel([{ x: 762, y: 300 }, { x: 771, y: 400 }, { x: 790, y: 440 }], 'L1');
await page.screenshot({ path: '/tmp/opencode/26-L1-result.jpg', type: 'jpeg', quality: 85 });
if (won) {
  console.log('button', await page.locator('#resultButton').textContent());
  await page.click('#resultButton');
  await page.waitForTimeout(1300);
  console.log('level now', await page.locator('#levelTitle').textContent());
  await page.screenshot({ path: '/tmp/opencode/26-L2-start.jpg', type: 'jpeg', quality: 85 });
  won = await clearLevel([{ x: 760, y: 320 }, { x: 790, y: 300 }, { x: 760, y: 430 }, { x: 830, y: 440 }], 'L2');
  await page.screenshot({ path: '/tmp/opencode/26-L2-result.jpg', type: 'jpeg', quality: 85 });
  if (won) {
    await page.click('#resultButton');
    await page.waitForTimeout(1300);
    console.log('level now', await page.locator('#levelTitle').textContent());
    await page.screenshot({ path: '/tmp/opencode/26-L3-start.jpg', type: 'jpeg', quality: 85 });
    won = await clearLevel([{ x: 730, y: 300 }, { x: 745, y: 400 }, { x: 745, y: 440 }, { x: 850, y: 420 }], 'L3');
    await page.screenshot({ path: '/tmp/opencode/26-L3-result.jpg', type: 'jpeg', quality: 85 });
  }
}
await browser.close();

