const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 }, deviceScaleFactor: 2 });
await page.goto('http://localhost:3002/?v=28', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.click('#playAttack');
await page.waitForTimeout(800);
const p = await page.evaluate(() => window.__skyway.screenOf(170, 390));
console.log('sling screen', p);
await page.screenshot({ path: '/tmp/opencode/28-sling.png', clip: { x: p.x - 110, y: p.y - 130, width: 240, height: 220 } });
const t = await page.evaluate(() => window.__skyway.screenOf(771, 300));
await page.screenshot({ path: '/tmp/opencode/28-tower.png', clip: { x: t.x - 130, y: t.y - 160, width: 260, height: 280 } });
await browser.close();

