import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/?v=29', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.click('#playAttack');
await page.waitForTimeout(1000);
let cur = (await page.evaluate(() => window.__skyway.state)).currentBird;
const from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
await page.mouse.move(from.x, from.y);
await page.mouse.down();
await page.mouse.move(from.x - 80, from.y + 50, { steps: 15 });
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/29-drag.jpg', type: 'jpeg', quality: 85 });
console.log('drag', await page.evaluate(() => window.__skyway.state.drag));
await page.mouse.up();
await page.waitForTimeout(3400);
await page.screenshot({ path: '/tmp/opencode/29-after.jpg', type: 'jpeg', quality: 85 });
console.log('progress', await page.locator('#progressText').textContent());
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?v=30', { waitUntil: 'load' });
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/opencode/30-menu.jpg', type: 'jpeg', quality: 82 });
await page.click('#playAttack');
await page.waitForTimeout(1100);
await page.screenshot({ path: '/tmp/opencode/30-attack.jpg', type: 'jpeg', quality: 82 });
const cur = (await page.evaluate(() => window.__skyway.state)).currentBird;
const from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
const p = await page.evaluate(() => window.__skyway.screenOf(771, 300));
console.log('sling', from, 'tower', p);
await page.mouse.move(from.x, from.y);
await page.mouse.down();
await page.mouse.move(from.x - 55, from.y + 35, { steps: 12 });
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/30-drag.jpg', type: 'jpeg', quality: 82 });
await page.mouse.up();
await page.waitForTimeout(3200);
await page.screenshot({ path: '/tmp/opencode/30-after.jpg', type: 'jpeg', quality: 82 });
await page.click('#buildTab');
await page.waitForTimeout(1100);
await page.screenshot({ path: '/tmp/opencode/30-build.jpg', type: 'jpeg', quality: 82 });
await browser.close();

