input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?v=31', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.click('#playAttack');
await page.waitForTimeout(1000);
await page.screenshot({ path: '/tmp/opencode/31-land-attack.jpg', type: 'jpeg', quality: 82 });
const box = await page.evaluate(() => ({ score: document.getElementById('score').getBoundingClientRect(), tray: document.getElementById('birdTray').getBoundingClientRect(), tabs: document.querySelector('.mode-switch').getBoundingClientRect() }));
console.log('layout', JSON.stringify(box));
await page.click('#buildTab');
await page.waitForTimeout(1100);
await page.screenshot({ path: '/tmp/opencode/31-land-build.jpg', type: 'jpeg', quality: 82 });
await page.click('[data-part="wheel"]');
await page.mouse.click(240, 280);
await page.mouse.click(280, 280);
await page.click('[data-part="balloon"]');
await page.mouse.click(260, 240);
await page.click('[data-part="balloon"]');
await page.mouse.click(260, 220);
await page.click('#driveBtn');
await page.waitForTimeout(900);
console.log('panel hidden while driving?', !(await page.locator('#buildPanel').isVisible()));
await page.screenshot({ path: '/tmp/opencode/31-land-driving.jpg', type: 'jpeg', quality: 82 });
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(900);
  if (await page.locator('#resultOverlay').isVisible()) break;
}
console.log('result', await page.locator('#resultOverlay').isVisible(), await page.locator('#resultTitle').textContent());
await page.screenshot({ path: '/tmp/opencode/31-land-result.jpg', type: 'jpeg', quality: 82 });
if (await page.locator('#resultOverlay').isVisible()) {
  await page.click('#resultButton');
  await page.waitForTimeout(900);
  console.log('panel back?', await page.locator('#buildPanel').isVisible());
  await page.screenshot({ path: '/tmp/opencode/31-land-rebuild.jpg', type: 'jpeg', quality: 82 });
}
await browser.close();

