input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002/?v=32', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.screenshot({ path: '/tmp/opencode/32-menu.jpg', type: 'jpeg', quality: 82 });
await page.click('#playAttack');
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/32-attack.jpg', type: 'jpeg', quality: 84 });
await page.keyboard.press('Escape');
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/32-pause.jpg', type: 'jpeg', quality: 84 });
console.log('paused', await page.locator('#pauseOverlay').isVisible());
await page.keyboard.press('Escape');
await page.click('#buildTab');
await page.waitForTimeout(1000);
// place two, undo one, clear
await page.mouse.click(300, 500);
await page.click('[data-part="wheel"]');
await page.mouse.click(340, 500);
console.log('parts2', (await page.evaluate(() => window.__skyway.state.build)).length, await page.evaluate(() => window.__skyway.state.build.map(o => o.kind)));
await page.click('#undoBtn');
console.log('after undo', await page.evaluate(() => window.__skyway.state.build.map(o => o.kind)));
await page.click('#clearBtn');
console.log('after clear', (await page.evaluate(() => window.__skyway.state.build)).length);
console.log('drive with no wheels ->', await page.locator('#notice').textContent());
await page.click('#driveBtn');
await page.waitForTimeout(300);
console.log('notice', await page.locator('#notice').textContent(), 'driving?', (await page.evaluate(() => window.__skyway.state)).driving);
await page.screenshot({ path: '/tmp/opencode/32-build.jpg', type: 'jpeg', quality: 84 });

// now build wheels only (no balloon) and drive -> should fall in gap and lose
await page.click('[data-part="wheel"]');
await page.mouse.click(286, 520);
await page.mouse.click(356, 520);
await page.click('#driveBtn');
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(1000);
  const s = await page.evaluate(() => window.__skyway.state);
  const r = await page.locator('#resultOverlay').isVisible();
  console.log(i, s.vehicle.x.toFixed(2), s.vehicle.y.toFixed(2), 'result', r);
  if (r) break;
}
console.log('fail title', await page.locator('#resultTitle').textContent().catch(() => ''));
await page.screenshot({ path: '/tmp/opencode/32-fail.jpg', type: 'jpeg', quality: 84 });
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1100, height: 720 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?v=33', { waitUntil: 'load' });
await page.waitForTimeout(1400);
await page.click('#playBuild');
await page.waitForTimeout(1200);
async function worldClick(wx, wy) {
  const p = await page.evaluate(([wx, wy]) => window.__skyway.screenOf(wx / 0.018 + 500, 462 - wy / 0.018), [wx, wy]);
  console.log('click', wx, wy, '->', p.x.toFixed(0), p.y.toFixed(0));
  await page.mouse.click(p.x, p.y);
}
await page.click('[data-part="wheel"]');
await worldClick(-4.6, 0.7);
await worldClick(-3.4, 0.7);
console.log('parts', JSON.stringify(await page.evaluate(() => window.__skyway.state.build)));
await page.screenshot({ path: '/tmp/opencode/33-built-wheels.jpg', type: 'jpeg', quality: 84 });
await page.click('#driveBtn');
for (let i = 0; i < 10; i++) {
  await page.waitForTimeout(900);
  const s = await page.evaluate(() => window.__skyway.state);
  const r = await page.locator('#resultOverlay').isVisible();
  console.log(i, s.vehicle.x.toFixed(2), s.vehicle.y.toFixed(2), 'result', r);
  if (r) break;
}
console.log('title', await page.locator('#resultTitle').textContent());
console.log('copy', await page.locator('#resultCopy').textContent());
await page.screenshot({ path: '/tmp/opencode/33-fail.jpg', type: 'jpeg', quality: 84 });
await browser.close();

