import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 760 } });
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?v=36', { waitUntil: 'load' });
await page.waitForTimeout(1400);
const G = 470;
function solvePull(from, target, biasT = 0) {
  let best = null;
  for (let T = 0.4; T <= 2.4; T += 0.02) {
    const vx = (target.x - from.x) / T;
    const vy = (target.y - from.y - 0.5 * G * T * T) / T;
    let f = 1.3, dxp, dyp, mag = 1e9;
    for (let k = 0; k < 10; k++) {
      dxp = -vx / (5.2 * f);
      dyp = -vy / (5.2 * f);
      mag = Math.hypot(dxp, dyp);
      f = Math.min(1.75, mag / 72);
    }
    if (mag <= 95) { best = { dxp, dyp, mag, T }; if (T >= biasT) return best; }
  }
  return best;
}
async function shootAt(target) {
  const st = await page.evaluate(() => window.__skyway.state);
  if (st.gameOver || !st.currentBird) return 'end';
  const cur = st.currentBird;
  const pull = solvePull(cur, target);
  if (!pull) return 'nosolve';
  const from = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x, cur.y]);
  const to = await page.evaluate(([x, y]) => window.__skyway.screenOf(x, y), [cur.x + pull.dxp, cur.y + pull.dyp]);
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  await page.mouse.move(to.x, to.y, { steps: 16 });
  await page.waitForTimeout(180);
  await page.mouse.up();
  await page.waitForTimeout(4000);
  return JSON.stringify(pull);
}
async function playLevel(i) {
  console.log('--- LEVEL', i, await page.locator('#levelTitle').textContent());
  for (let s = 0; s < 6; s++) {
    const st = await page.evaluate(() => window.__skyway.state);
    if (st.gameOver) break;
    const alive = st.pigs.filter(p => p.alive);
    if (!alive.length) break;
    console.log('state birds used', st.birds.map(b => b.used), 'alive pigs', alive.map(p => [p.x, p.y]));
    const tgt = alive.sort((a, b) => a.y - b.y)[0];
    console.log('shot', s + 1, 'at', tgt.x, tgt.y);
    console.log('pull', await shootAt({ x: tgt.x, y: tgt.y }));
    console.log('score', await page.locator('#score').textContent(), 'progress', await page.locator('#progressText').textContent(), 'result', await page.locator('#resultOverlay').isVisible());
    await page.screenshot({ path: `/tmp/opencode/36-L${i}-s${s + 1}.jpg`, type: 'jpeg', quality: 84 });
  }
  return page.locator('#resultOverlay').isVisible();
}
await page.click('#playAttack');
await page.waitForTimeout(900);
console.log('L1', await playLevel(1));
if (await page.locator('#resultOverlay').isVisible()) { await page.screenshot({ path: '/tmp/opencode/36-L1-result.jpg', type: 'jpeg', quality: 84 }); await page.click('#resultButton'); await page.waitForTimeout(1200); }
console.log('L2', await playLevel(2));
if (await page.locator('#resultOverlay').isVisible()) { await page.screenshot({ path: '/tmp/opencode/36-L2-result.jpg', type: 'jpeg', quality: 84 }); await page.click('#resultButton'); await page.waitForTimeout(1200); }
console.log('L3', await playLevel(3));
await page.screenshot({ path: '/tmp/opencode/36-L3-end.jpg', type: 'jpeg', quality: 84 });
await browser.close();
